package com.lmspilot.learning.domain; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="xapi_statements") public class XapiStatementEntity { @Id public UUID id=UUID.randomUUID(); @Column(nullable=false) public UUID actorUserId; @Column(nullable=false,length=160) public String verb=""; @Column(nullable=false) public UUID objectId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) public XapiObjectType objectType=XapiObjectType.OTHER; public UUID courseId; @Column(columnDefinition="text") public String resultJson; @Column(columnDefinition="text") public String contextJson; @Column(nullable=false) public Instant occurredAt=Instant.now(); @Column(nullable=false) public Instant storedAt=Instant.now(); public XapiStatementEntity(){} }
